-- Time tracking cell (time), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA time;

CREATE FUNCTION time.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE time.time_entries (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    task_id                  bigint NOT NULL,
    started_at               timestamptz NOT NULL,
    ended_at                 timestamptz,
    duration_seconds         integer,
    source                   text NOT NULL DEFAULT 'manual',
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX time_entries_legacy ON time.time_entries (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX time_entries_task_id ON time.time_entries (workspace_id, task_id);

CREATE TABLE time.time_logs (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    log_date                 text NOT NULL CHECK (length(log_date) >= 1),
    domain                   text NOT NULL CHECK (length(domain) >= 1),
    activity                 text NOT NULL CHECK (length(activity) >= 1),
    minutes                  integer NOT NULL DEFAULT 0,
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX time_logs_legacy ON time.time_logs (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE time.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('time-entry', 'time-log')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE time.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON time.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['time_entries', 'time_logs', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE time.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE time.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON time.%I'
                       ' USING (workspace_id = time.current_workspace())'
                       ' WITH CHECK (workspace_id = time.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA time TO time_api;
GRANT EXECUTE ON FUNCTION time.current_workspace() TO time_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON time.time_entries, time.time_logs TO time_api;
GRANT USAGE ON SEQUENCE time.time_entries_id_seq, time.time_logs_id_seq TO time_api;
GRANT SELECT, INSERT ON time.create_keys TO time_api;
GRANT SELECT, INSERT ON time.outbox TO time_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON time.outbox TO time_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON time.outbox TO time_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA time TO time_publisher;
GRANT SELECT ON time.outbox TO time_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON time.outbox TO time_publisher;
